def apply_openapi_extensions(spec: dict) -> None:
    existing_names = {t['name'] for t in spec.get('tags', []) if isinstance(t, dict) and 'name' in t}
    for tag in EXTRA_TAGS:
        if tag['name'] not in existing_names:
            spec.setdefault('tags', []).append(tag)
            existing_names.add(tag['name'])
    spec.setdefault('components', {}).setdefault('schemas', {}).update(EXTRA_SCHEMAS)
    spec.setdefault('paths', {}).update(EXTRA_PATHS)
